// LEVEL HELPERS
// ═══════════════════════════════════════════════════════════════
function getLevel(badgeCount){
  let lvl = LEVELS[0];
  for(const l of LEVELS){ if(badgeCount >= l.min) lvl = l; }
  return lvl;
}
function getNextLevel(badgeCount){
  for(const l of LEVELS){ if(badgeCount < l.min) return l; }
  return null; // maxed out
}

// ═══════════════════════════════════════════════════════════════
// BADGE MILESTONE CELEBRATION (confetti pop-up on level-up)
// ═══════════════════════════════════════════════════════════════
function checkForLevelUp(oldBadgesData){
  if(!CU || isAdmin) return; // only celebrate for the athlete viewing their own progress
  if(!oldBadgesData) return; // first load, nothing to compare against
  const oldCount = oldBadgesData[CU.uid];
  const newCount = badges[CU.uid];
  if(oldCount === undefined || newCount === undefined) return;
  if(newCount <= oldCount) return; // only celebrate increases

  const oldLevel = getLevel(oldCount);
  const newLevel = getLevel(newCount);
  if(newLevel.key !== oldLevel.key && newLevel.key !== 'none'){
    showLevelUpCelebration(newLevel);
  }
}

function showLevelUpCelebration(level){
  const overlay = document.getElementById('levelUpOverlay');
  if(!overlay) return;
  document.getElementById('levelUpMedal').textContent =
    level.key==='bronze'?'🥉':level.key==='silver'?'🥈':level.key==='gold'?'🥇':'💎';
  document.getElementById('levelUpLevelName').textContent = level.label;
  overlay.style.display = 'flex';
  launchConfetti();
  if(level.key==='diamond') launchFireworks();
  setTimeout(()=>{ overlay.classList.add('show'); }, 10);
}

function closeLevelUpCelebration(){
  const overlay = document.getElementById('levelUpOverlay');
  overlay.classList.remove('show');
  setTimeout(()=>{ overlay.style.display = 'none'; }, 300);
}

function launchConfetti(){
  const container = document.getElementById('confettiContainer');
  if(!container) return;
  container.innerHTML = '';
  const colors = ['#9b30ff','#c084fc','#ffc857','#7dd8ff','#ff6b81','#ffffff'];
  const pieceCount = 80;
  for(let i=0; i<pieceCount; i++){
    const piece = document.createElement('div');
    piece.className = 'confetti-piece';
    piece.style.left = Math.random()*100 + '%';
    piece.style.background = colors[Math.floor(Math.random()*colors.length)];
    piece.style.animationDelay = (Math.random()*0.5) + 's';
    piece.style.animationDuration = (2.5 + Math.random()*1.5) + 's';
    piece.style.width = piece.style.height = (6+Math.random()*6) + 'px';
    piece.style.borderRadius = Math.random()>0.5 ? '50%' : '2px';
    container.appendChild(piece);
  }
  setTimeout(()=>{ container.innerHTML = ''; }, 4500);
}

// Little firework bursts for reaching Diamond level — a few staggered
// bursts of sparks radiating outward from random points on screen.
function launchFireworks(){
  const container = document.getElementById('fireworkContainer');
  if(!container) return;
  container.innerHTML = '';
  const colors = ['#7dd8ff','#ffc857','#ff6b81','#c084fc','#ffffff','#9b30ff'];
  const burstCount = 6;
  const sparksPerBurst = 18;

  for(let b=0; b<burstCount; b++){
    const burstDelay = b * 260 + Math.random()*150;
    setTimeout(()=>{
      const originX = 15 + Math.random()*70; // vw%
      const originY = 15 + Math.random()*50; // vh%
      const color = colors[Math.floor(Math.random()*colors.length)];
      for(let s=0; s<sparksPerBurst; s++){
        const angle = (s / sparksPerBurst) * Math.PI * 2;
        const distance = 60 + Math.random()*50;
        const dx = Math.cos(angle) * distance;
        const dy = Math.sin(angle) * distance;
        const spark = document.createElement('div');
        spark.className = 'firework-spark';
        spark.style.left = originX + '%';
        spark.style.top = originY + '%';
        spark.style.color = color;
        spark.style.background = color;
        spark.style.setProperty('--dx', dx + 'px');
        spark.style.setProperty('--dy', dy + 'px');
        spark.style.animationDelay = (Math.random()*0.08) + 's';
        container.appendChild(spark);
      }
    }, burstDelay);
  }

  setTimeout(()=>{ container.innerHTML = ''; }, burstCount*260 + 1600);
}

// ═══════════════════════════════════════════════════════════════
// SHARE MY PROGRESS — generates a downloadable shareable card image
// ═══════════════════════════════════════════════════════════════
async function openShareCard(){
  if(!CU || isAdmin) return;
  const modal = document.getElementById('shareCardModal');
  const canvasWrap = document.getElementById('shareCardCanvasWrap');
  canvasWrap.innerHTML = '<p style="text-align:center;color:var(--ink-faint);padding:40px;font-size:12px;">Generating your card...</p>';
  openModal('shareCardModal');

  try{
    const snap = await dbGet('lb_users/'+CU.uid);
    const profile = snap.val() || {};
    const badgeCount = badges[CU.uid] || 0;
    const lvl = getLevel(badgeCount);
    const avatarUrl = buildAvatarUrl({...DEFAULT_AVATAR, ...(profile.avatar||{})});

    const canvas = document.createElement('canvas');
    const W = 600, H = 750;
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext('2d');

    // Background gradient
    const bgGrad = ctx.createLinearGradient(0,0,W,H);
    bgGrad.addColorStop(0, '#0d1b3e');
    bgGrad.addColorStop(1, '#1b3270');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0,0,W,H);

    // Purple glow accents
    const glow1 = ctx.createRadialGradient(W*0.15,H*0.05,0,W*0.15,H*0.05,260);
    glow1.addColorStop(0,'rgba(155,48,255,0.25)');
    glow1.addColorStop(1,'rgba(155,48,255,0)');
    ctx.fillStyle = glow1;
    ctx.fillRect(0,0,W,H);

    // Header text
    ctx.textAlign = 'center';
    ctx.fillStyle = '#9b30ff';
    ctx.font = '700 16px Arial';
    ctx.fillText('IN SYNCH CAMP · 2026 LEADERBOARD', W/2, 60);

    // Load and draw avatar
    const avatarImg = await loadImageSafe(avatarUrl);
    const avSize = 220, avX = W/2 - avSize/2, avY = 90;
    ctx.save();
    ctx.beginPath();
    ctx.arc(W/2, avY+avSize/2, avSize/2, 0, Math.PI*2);
    ctx.closePath();
    ctx.fillStyle = '#eef2ff';
    ctx.fill();
    ctx.clip();
    if(avatarImg) ctx.drawImage(avatarImg, avX, avY, avSize, avSize);
    ctx.restore();

    // Ring around avatar
    ctx.beginPath();
    ctx.arc(W/2, avY+avSize/2, avSize/2+4, 0, Math.PI*2);
    ctx.strokeStyle = '#9b30ff';
    ctx.lineWidth = 5;
    ctx.stroke();

    // Name
    ctx.fillStyle = '#ffffff';
    ctx.font = '700 32px Arial';
    ctx.fillText(displayName(profile.name||CU.name), W/2, avY+avSize+55);

    // Club
    if(profile.club){
      ctx.fillStyle = 'rgba(238,242,255,0.6)';
      ctx.font = '600 16px Arial';
      ctx.fillText(profile.club, W/2, avY+avSize+82);
    }

    // Badge count pill
    const pillY = avY+avSize+115;
    ctx.fillStyle = 'rgba(255,200,87,0.15)';
    roundRectPath(ctx, W/2-130, pillY-28, 260, 56, 28);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,200,87,0.4)';
    ctx.lineWidth = 2;
    roundRectPath(ctx, W/2-130, pillY-28, 260, 56, 28);
    ctx.stroke();
    ctx.fillStyle = '#ffc857';
    ctx.font = '700 26px Arial';
    ctx.fillText(`🌟 ${badgeCount} Badges`, W/2, pillY+9);

    // Level
    ctx.fillStyle = '#9b30ff';
    ctx.font = '700 20px Arial';
    ctx.fillText(`${lvl.label} Level`, W/2, pillY+55);

    // Footer
    ctx.fillStyle = 'rgba(238,242,255,0.35)';
    ctx.font = '600 13px Arial';
    ctx.fillText('leaderboard.insynchcamp.com', W/2, H-30);

    canvasWrap.innerHTML = '';
    canvas.style.width = '100%';
    canvas.style.borderRadius = '16px';
    canvasWrap.appendChild(canvas);

    // Wire up download button
    document.getElementById('btnDownloadShareCard').onclick = () => {
      const link = document.createElement('a');
      link.download = `insynch-progress-${displayName(profile.name||CU.name).replace(/\s/g,'-')}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    };
  } catch(ex){
    canvasWrap.innerHTML = '<p style="text-align:center;color:var(--coral);padding:40px;font-size:12px;">Could not generate the card. Please try again.</p>';
  }
}

function loadImageSafe(url){
  return new Promise((resolve)=>{
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = url;
  });
}

function roundRectPath(ctx, x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x+r, y);
  ctx.arcTo(x+w, y, x+w, y+h, r);
  ctx.arcTo(x+w, y+h, x, y+h, r);
  ctx.arcTo(x, y+h, x, y, r);
  ctx.arcTo(x, y, x+w, y, r);
  ctx.closePath();
}

// ═══════════════════════════════════════════════════════════════
// AVATAR SVG RENDERER
// ═══════════════════════════════════════════════════════════════
function buildAvatarUrl(av){
  av = av || DEFAULT_AVATAR;

  // Defensive lookups: if a saved value doesn't match any known option
  // (e.g. leftover data from an earlier version of the avatar builder),
  // silently fall back to the default instead of sending a bad value to the API.
  const skinObj = SKIN_TONES.find(s=>s.id===av.skin) || SKIN_TONES.find(s=>s.id===DEFAULT_AVATAR.skin);
  const hairColorObj = HAIR_COLORS.find(h=>h.id===av.hairColor) || HAIR_COLORS.find(h=>h.id===DEFAULT_AVATAR.hairColor);
  const clothColorObj = CLOTHING_COLORS.find(c=>c.id===av.clothingColor) || CLOTHING_COLORS.find(c=>c.id===DEFAULT_AVATAR.clothingColor);
  const exprObj = EXPRESSIONS.find(e=>e.id===av.expression) || EXPRESSIONS.find(e=>e.id===DEFAULT_AVATAR.expression);
  const hairStyleObj = HAIR_STYLES.find(h=>h.id===av.hairStyle);
  const hairStyle = hairStyleObj ? hairStyleObj.id : DEFAULT_AVATAR.hairStyle;
  const accessoryObj = ACCESSORIES.find(a=>a.id===av.accessory);
  const accessory = accessoryObj ? accessoryObj.id : DEFAULT_AVATAR.accessory;
  const facialHairObj = FACIAL_HAIR.find(f=>f.id===av.facialHair);
  const facialHair = facialHairObj ? facialHairObj.id : DEFAULT_AVATAR.facialHair;

  const params = new URLSearchParams();
  params.set('seed', 'static');
  params.set('top', hairStyle);
  params.set('topProbability', '100');
  params.set('hairColor', hairColorObj.hex);
  params.set('hairColorProbability', '100');
  params.set('skinColor', skinObj.hex);
  params.set('clothing', 'shirtCrewNeck');
  params.set('clothesColor', clothColorObj.hex);
  params.set('mouth', exprObj.mouth);
  params.set('mouthProbability', '100');
  params.set('eyes', exprObj.eyes);
  params.set('eyesProbability', '100');
  params.set('eyebrows', exprObj.eyebrow);
  params.set('eyebrowsProbability', '100');
  // Only send accessories params when an actual accessory is chosen.
  // Omitting the param entirely (rather than sending an empty/blank value)
  // avoids enum-validation errors from the API for the "none" case.
  if(accessory && accessory !== 'blank'){
    params.set('accessories', accessory);
    params.set('accessoriesProbability', '100');
  }
  if(facialHair && facialHair !== 'blank'){
    params.set('facialHair', facialHair);
    params.set('facialHairProbability', '100');
    params.set('facialHairColor', hairColorObj.hex);
  } else {
    params.set('facialHairProbability', '0');
  }
  params.set('backgroundColor', 'transparent');

  return DICEBEAR_BASE + '?' + params.toString();
}

const INSYNCH_LOGO_URL = 'https://i.ibb.co/4n7TcPdP/Front-in-synch.png';

function avatarBadgeHTML(av, size){
  size = size || 40;
  const logoChoice = (av && av.logoChoice) || DEFAULT_AVATAR.logoChoice;
  const clubLogoUrl = av && av._clubLogoUrl;
  const badgeSize = Math.max(14, Math.round(size * 0.34));
  const logoUrl = (logoChoice === 'club' && clubLogoUrl) ? clubLogoUrl : INSYNCH_LOGO_URL;
  return `<div style="position:absolute;bottom:-2px;right:-2px;width:${badgeSize}px;height:${badgeSize}px;border-radius:50%;background:#fff;border:2px solid var(--bg-deep);overflow:hidden;display:flex;align-items:center;justify-content:center;">
    <img src="${logoUrl}" style="width:100%;height:100%;object-fit:cover;" loading="lazy" alt="">
  </div>`;
}

function renderAvatarSVG(av, size){
  size = size || 40;
  const url = buildAvatarUrl(av);
  return `<div style="position:relative;width:${size}px;height:${size}px;flex-shrink:0;">
    <div style="width:100%;height:100%;border-radius:50%;overflow:hidden;background:#eef2ff;">
      <img src="${url}" style="width:100%;height:100%;object-fit:cover;" loading="lazy" alt="">
    </div>
    ${avatarBadgeHTML(av, size)}
  </div>`;
}

function avatarThumbHTML(av, size){
  return renderAvatarSVG(av, size||40);
}

function renderAthleteAvatar(athlete, size){
  if(!athlete) return renderAvatarSVG(DEFAULT_AVATAR, size);
  const av = {...(athlete.avatar||DEFAULT_AVATAR)};
  av._clubName = athlete.club || '';
  av._clubLogoUrl = getClubLogo(athlete.club);
  return renderAvatarSVG(av, size);
}

